#!/usr/bin/env python3
"""Original SH-2 sprite-window/shadow/palette-blend guest. MIT: LICENSE.

ST-058 §§8.1/9.1/9.2/14.1. All pixels/attributes and device controls are
written by guest instructions; no host rendering or firmware is used.
"""
import argparse
import hashlib
from pathlib import Path
import struct
from build_effects import assembler, store
HERE=Path(__file__).resolve().parent

def build():
    s='; Original MIT sprite composition guest. ST-058 §§8/9/14.\n'
    for offset,value in [(0x10,0x4444),(0x12,0xEEEE),
                         (0x20,0x101),(0x28,0x32),(0x78,1),(0x7C,1),
                         (0xF8,1),(0xF0,3),(0xE0,0x3013),(0xE2,0x21),
                         (0xEC,0x40),(0x100,15),(0xD0,0x20),(0xAC,3),(0xAE,0xF000)]:
        s+=store(0x25F80000+offset,value)
    s+=store(0x25E7E000,0xFC00)+store(0x25F00002,0x83E0)
    for x,value in enumerate([0x8000,1,0x07FE,0x8001,0,0x8000,0x87FE,0]):
        s+=store(0x25E00000+x*2,0x801F)
        s+=store(0x25C80000+x*2,value)
    s+=store(0x25D00002,3)  # Guest requests display/draw buffer exchange.
    s+=store(0x25F80000,0x8000)
    s+=store(0x0600B000,0x600D,'l')+'park:\nsleep\nbra park\nnop\n'
    rom=bytearray(524288)
    struct.pack_into('>II',rom,0,0x200,0x06100000)
    code=assembler.assemble(s,base=0x200)
    rom[0x200:0x200+len(code)]=code
    text=['# Original sprite-composition guest ROM. MIT: adjacent LICENSE.',
          '# Generated by build_sprite_effects.py; unspecified bytes are zero.']
    for at in range(0,len(rom),16):
        data=rom[at:at+16]
        if any(data): text.append(f'{at:04X} '+' '.join(f'{w:04X}' for w in struct.unpack('>8H',data)))
    return s,'\n'.join(text)+'\n',hashlib.sha256(rom).hexdigest()

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');args=p.parse_args()
    source,text,digest=build()
    for path,value in [(HERE/'sprite-effects.s',source),(HERE/'sprite-effects.hex',text)]:
        if args.check: assert path.read_text()==value,f'Rebuild {path.name}'
        else: path.write_text(value)
    print(f'{"Verified" if args.check else "Built"} sprite-effects.hex; expanded ROM SHA-256 {digest}')
